          "type": "datasource",
          "id": "prometheus",
          "name": "Prometheus",
          "version": "1.0.0"
        },
        {
          "type": "panel",
          "id": "stat",
          "name": "Stat",
          "version": ""
        },
        {
          "type": "panel",
          "id": "timeseries",
          "name": "Time series",
          "version": ""
        },
        {
          "type": "panel",
          "id": "gauge",
          "name": "Gauge",
          "version": ""
        },
        {
          "type": "panel",
          "id": "table",
          "name": "Table",
          "version": ""
        }
      ],
      "annotations": {
        "list": [
          {
            "builtIn": 1,
            "datasource": { "type": "grafana", "uid": "-- Grafana --" },
            "enable": true,
            "hide": true,
            "iconColor": "rgba(0, 211, 255, 1)",
            "name": "Annotations & Alerts",
            "type": "dashboard"
          },
          {
            "datasource": { "type": "grafana", "uid": "-- Grafana --" },
            "enable": true,
            "hide": false,
            "iconColor": "#5794F2",
            "name": "Deployments",
            "type": "tags",
            "tags": ["deployment"],
            "builtIn": 0,
            "limit": 100,
            "showIn": 0,
            "step": "60s"
          }
        ]
      },
      "description": "Multi-window, multi-burn-rate SLO dashboard.  Uses the slo:sli_error:ratio_rate<window> recording rules produced by the availability-slo PrometheusRule template (observability/prometheus/slos/availability-slo.yaml).",
      "editable": true,
      "fiscalYearStartMonth": 0,
      "graphTooltip": 1,
      "id": null,
      "links": [],
      "panels": [
        {
          "collapsed": false,
          "gridPos": { "h": 1, "w": 24, "x": 0, "y": 0 },
          "id": 10,
          "title": "Current Status",
          "type": "row"
        },
        {
          "datasource": { "type": "prometheus", "uid": "${datasource}" },
          "description": "Current 5-minute error rate as a percentage of total requests.  Colour thresholds reflect the burn-rate multiplier against the error budget:\n  • Green  = below 1× budget burn (on track)\n  • Yellow = 1×–6× (elevated; may page on the slow-burn alert)\n  • Orange = 6×–14× (high burn; fast-burn alert may be firing)\n  • Red    = above 14× (critical; fast-burn alert should be firing)",
          "fieldConfig": {
            "defaults": {
              "color": { "mode": "thresholds" },
              "decimals": 4,
              "mappings": [],
              "thresholds": {
                "mode": "absolute",
                "steps": [
                  { "color": "green", "value": null },
                  {
                    "color": "yellow",
                    "value": null,
                    "__expr": "(1 - ${slo_target}) * 1"
