  default     = "standard" # <-- CHANGE THIS: standard, gp2, gp3, or io1

  validation {
    condition     = can(regex("^[a-z0-9]+$", var.storage_class_name))
    error_message = "storage_class_name must contain only lowercase letters and numbers."
  }
}

variable "storage_size" {
  description = "Size of the EBS volume in GB (if using EBS)"
  type        = number
  default     = 100 # <-- CHANGE THIS: size to your workload

  validation {
    condition     = var.storage_size > 0
    error_message = "storage_size must be greater than 0."
  }
}

variable "storage_iops" {
  description = "IOPS for the EBS volume (if using EBS)"
  type        = number
  default     = 3000 # <-- CHANGE THIS: adjust for I/O intensive workloads

  validation {
    condition     = var.storage_iops > 0
    error_message = "storage_iops must be greater than 0."
  }
}

variable "storage_throughput" {
  description = "Throughput for the EBS volume in MB/s (if using EBS)"
  type        = number
  default     = 50 # <-- CHANGE THIS: adjust for throughput intensive workloads

  validation {
    condition     = var.storage_throughput > 0
    error_message = "storage_throughput must be greater than 0."
  }
}

variable "storage_volume_type" {
  description = "Volume type for EBS volume (if using EBS)"
  type        = string
  default     = "gp3" # <-- CHANGE THIS: gp2, gp3, or io1

  validation {
    condition     = contains(["gp2", "gp3", "io1"], var.storage_volume_type)
    error_message = "storage_volume_type must be one of: gp2, gp3, or io1."
  }
}

variable "storage_performance_mode" {
  description = "Performance mode for EFS file system (if using EFS)"
  type        = string
  default     = "performance" # <-- CHANGE THIS: performance or general-purpose

  validation {
    condition     = contains(["performance", "general-purpose"], var.storage_performance_mode)
    error_message = "storage_performance_mode must be one of: performance or general-purpose."
  }
}

variable "storage_throughput_mode" {
  description = "Throughput mode for EFS file system (if using EFS)"
  type        = string
  default     = "bursting" # <-- CHANGE THIS: bursting or provisioned

  validation {
    condition     = contains(["bursting", "provisioned"], var.storage_throughput_mode)
    error_message = "storage_throughput_mode must be one of: bursting or provisioned."
  }
}

variable "storage_encryption" {
  description = "Enable encryption for EFS file system (if using EFS)"
  type        = bool
  default     = true # <-- CHANGE THIS: set to false to disable encryption

  validation {
    condition     = can(var.storage_encryption ? true : false)
    error_message = "storage_encryption must be a boolean."
  }
}

variable "storage_multi_attached" {
  description = "Enable multi-attached volume for EBS (if using EBS)"
  type        = bool
  default     = false # <-- CHANGE THIS: set to true for multi-attached volumes

  validation {
    condition     = can(var.storage_multi_attached ? true : false)
    error_message = "storage_multi_attached must be a boolean."
  }
}

variable "storage_force_destroy" {
  description = "Force destroy S3 bucket on deletion (if using S3)"
  type        = bool
  default     = false # <-- CHANGE THIS: set to true to force destroy

  validation {
    condition     = can(var.storage_force_destroy ? true : false)
    error_message = "storage_force_destroy must be a boolean."
  }
}

# ============================================================
# TEMPLATE: Terraform — Amazon Elastic Kubernetes Service (EKS)
# WHEN TO USE: Provisioning a production-ready EKS cluster on AWS
# PREREQUISITES: AWS account, AWS CLI authenticated
# SECRETS NEEDED: None (uses aws configure or IAM role)
# WHAT TO CHANGE: Lines marked with # <-- CHANGE THIS
# RELATED FILES: cd/targets/aws-eks/, cd/kubernetes/
# MATURITY: Stable
# LAYOUT: versions.tf (providers), network.tf (VPC), ecr.tf (registry),
#         iam.tf (roles), eks.tf (cluster/node groups), security-groups.tf,
#         backup.tf (DR/backup), locals.tf (tags)
# ============================================================

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 6.61.0" # <-- CHANGE THIS: pin to latest stable
    }
  }

  # Uncomment and configure for remote state
  # backend "s3" {
  #   bucket         = "my-terraform-state"
  #   key            = "eks/terraform.tfstate"
  #   region         = "us-east-1"
  #   dynamodb_table = "terraform-locks"
  #   encrypt        = true
  # }
}

provider "aws" {
  region = var.aws_region

  default_tags {
    tags = local.common_tags
  }
}

# Used by the optional cross-region RDS read replica in backup.tf.
provider "aws" {
  alias  = "dr_region"
  region = var.dr_region

  default_tags {
    tags = local.common_tags
  }
}

locals {
  common_tags = {
    CostCenter  = var.cost_center
    Owner       = var.owner
    Project     = var.project
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

# ---------------------------------------------
# API Gateway (HTTP API — simpler and cheaper than REST API)
# ---------------------------------------------
resource "aws_apigatewayv2_api" "main" {
  name          = "api-${var.project}-${var.environment}"
  protocol_type = "HTTP"
  description   = "HTTP API Gateway for ${var.project} (${var.environment})"

  cors_configuration {
    allow_headers = ["Content-Type", "Authorization"]
    allow_methods = ["GET", "POST", "PUT", "DELETE", "OPTIONS"]
    allow_origins = var.cors_allowed_origins # <-- CHANGE THIS
    max_age       = 3600
  }
}

resource "aws_apigatewayv2_stage" "main" {
  api_id      = aws_apigatewayv2_api.main.id
  name        = "$default"
  auto_deploy = true

  access_log_settings {
    destination_arn = aws_cloudwatch_log_group.api_gateway.arn
    format = jsonencode({
      requestId        = "$context.requestId"
      ip               = "$context.identity.sourceIp"
      requestTime      = "$context.requestTime"
      httpMethod       = "$context.httpMethod"
      routeKey         = "$context.routeKey"
      status           = "$context.status"
      protocol         = "$context.protocol"
      responseLength   = "$context.responseLength"
      integrationError = "$context.integrationErrorMessage"
    })
  }
}

resource "aws_cloudwatch_log_group" "api_gateway" {
  name              = "/aws/apigateway/${var.project}-${var.environment}"
  retention_in_days = 30
}

resource "aws_apigatewayv2_integration" "lambda" {
  api_id                 = aws_apigatewayv2_api.main.id
  integration_type       = "AWS_PROXY"
  integration_uri        = var.lambda_invoke_arn
  payload_format_version = "2.0"
}

# Catch-all route — Lambda handles all routing internally
resource "aws_apigatewayv2_route" "default" {
  api_id    = aws_apigatewayv2_api.main.id
  route_key = "$default"
  target    = "integrations/${aws_apigatewayv2_integration.lambda.id}"
}

# Allow API Gateway to invoke the Lambda function
resource "aws_lambda_permission" "api_gateway" {
  statement_id  = "AllowAPIGatewayInvoke"
  action        = "lambda:InvokeFunction"
  function_name = var.lambda_function_name
  principal     = "apigateway.amazonaws.com"
  source_arn    = "${aws_apigatewayv2_api.main.execution_arn}/*/*"
}

output "api_endpoint" {
  value = aws_apigatewayv2_api.main.api_endpoint
}

output "api_id" {
  value = aws_apigatewayv2_api.main.id
}

variable "project" {
  type = string
}

variable "environment" {
  type = string
}

variable "cors_allowed_origins" {
  type = list(string)
}

variable "lambda_function_name" {
  type = string
}

variable "lambda_invoke_arn" {
  type = string
}

# ---------------------------------------------
# IAM Role for Lambda
# ---------------------------------------------
resource "aws_iam_role" "lambda" {
  name = "role-lambda-${var.project}-${var.environment}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Action = "sts:AssumeRole"
      Effect = "Allow"
      Principal = {
        Service = "lambda.amazonaws.com"
      }
    }]
  })
}

# Basic execution role (CloudWatch Logs access)
resource "aws_iam_role_policy_attachment" "lambda_basic" {
  role       = aws_iam_role.lambda.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"
}

# VPC access (only needed if Lambda runs inside a VPC)
# resource "aws_iam_role_policy_attachment" "lambda_vpc" {
#   role       = aws_iam_role.lambda.name
#   policy_arn = "arn:aws:iam::aws:policy/service-role/AWSLambdaVPCAccessExecutionRole"
# }

output "role_arn" {
  value = aws_iam_role.lambda.arn
}

output "policy_attachment_id" {
  value = aws_iam_role_policy_attachment.lambda_basic.id
}

variable "project" {
  type = string
}

variable "environment" {
  type = string
}

# ---------------------------------------------
# CloudWatch Log Group + Lambda Function
# ---------------------------------------------
resource "aws_cloudwatch_log_group" "lambda" {
  name              = "/aws/lambda/${var.project}-${var.environment}"
  retention_in_days = 30
}

resource "aws_lambda_function" "main" {
  function_name = "${var.project}-${var.environment}"
  role          = var.role_arn
  handler       = var.handler # <-- CHANGE THIS: e.g., "app.handler" for Python, "index.handler" for Node
  runtime       = var.runtime # <-- CHANGE THIS: e.g., "python3.12", "nodejs20.x"
  timeout       = var.timeout
  memory_size   = var.memory_size

  # Option 1: Deploy from a zip file (for initial setup — CI/CD updates this later)
  filename         = var.lambda_zip_path
  source_code_hash = filebase64sha256(var.lambda_zip_path)

  # Option 2: Deploy from a container image (uncomment and remove filename/handler/runtime above)
  # package_type = "Image"
  # image_uri    = "${var.ecr_repository_url}:latest"

  environment {
    variables = {
      ENVIRONMENT = var.environment
      LOG_LEVEL   = var.environment == "prod" ? "INFO" : "DEBUG"
      # <-- CHANGE THIS: add your application environment variables
    }
  }

  tracing_config {
    mode = "Active" # Enable AWS X-Ray tracing
  }

  depends_on = [
    var.role_policy_attachment_id,
    aws_cloudwatch_log_group.lambda,
  ]
}

output "function_name" {
  value = aws_lambda_function.main.function_name
}

output "function_arn" {
  value = aws_lambda_function.main.arn
}

output "invoke_arn" {
  value = aws_lambda_function.main.invoke_arn
}

output "log_group_name" {
  value = aws_cloudwatch_log_group.lambda.name
}

variable "project" {
  type = string
}

variable "environment" {
  type = string
}

variable "role_arn" {
  type = string
}

variable "role_policy_attachment_id" {
  description = "Forces this module to wait until the IAM policy is attached to the role"
  type        = string
}

variable "handler" {
  type = string
}

variable "runtime" {
  type = string
}

variable "timeout" {
  type = number
}

variable "memory_size" {
  type = number
}

variable "lambda_zip_path" {
  type = string
}

